  // real one pickPositionRelativeTo's own isAnchorTooBig rejects" (see its
  // own doc) — nothing left to dispatch on here.
  const positioner = positionCallout(calloutElement, visualAnchorElement, {
    debug,
    originalAnchorElement
  });
  addTeardown(() => {
    positioner.stop();
  });
