  useDisplayedLayoutEffect(
    focusableElementRef,
    (el, e) => {
      return triggerAutofocus(e);
    },
    [],
  );

  // useEffect(() => {
  //   if (autoFocus) {
  //     const focusableElement = focusableElementRef.current;
  //     focusableElement.scrollIntoView({ inline: "nearest", block: "nearest" });
  //   }
  // }, []);

